window.kbPageData["views/entry/k-15740b31266d40d6"] = {"key":"entry/k-15740b31266d40d6","state":{"route":"entry/k-15740b31266d40d6"},"node":{"id":"k-15740b31266d40d6","mode":"k","title":"《生成式人工智能服务管理暂行办法》","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["《生成式人工智能服务管理暂行办法》的规制对象与治理原则"],"qs":["江苏 2024 A类 行测#11"],"current":true,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"2023年7月，国家网信办等七部门联合公布《生成式人工智能服务管理暂行办法》，规范利用生成式人工智能技术提供文本、图片、音频、视频等内容生成的服务。办法鼓励创新应用，并兼顾个人合法权益、公共利益和国家安全。","review":{"definition":"2023年7月，国家网信办等七部门联合公布《生成式人工智能服务管理暂行办法》，规范利用生成式人工智能技术提供文本、图片、音频、视频等内容生成的服务。办法鼓励创新应用，并兼顾个人合法权益、公共利益和国家安全。","explanation":"B项对应题干所说的“内容生成能力”，即办法将具备这类能力的模型及相关技术的服务应用纳入专门治理。材料同时提出鼓励各行业、各领域创新和探索优化应用场景，因此不能推出A项所说的对应用场景实施统一管理。C项涉及利用个人信息进行自动化决策时的不合理差别待遇，解析将其对应到《个人信息保护法》。D项所说的应用处于起步阶段，也无法由文件名称中的“暂行”推出。","references":[],"evidence":"具有文本图片、音频、视频等内容生成能力的模型及相关技术的服务应用加以规范","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 A类 行测#11":{"paper":"江苏 2024 A类 行测","n":11,"mod":"常识判断","src":["f8fec75f67d6d1ba5759.pdf",2],"asrc":["0126a1c8aceee632ea2b.pdf",4],"card":"0d0b36fb4c369dfdebd9403c","links":[{"id":"k-15740b31266d40d6","role":"直接考查","why":"办法将具备内容生成能力的模型及相关技术的服务应用纳入规范，并兼顾鼓励创新与安全治理。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-15740b31266d40d6":[["江苏 2024 A类 行测#11"]]}};
